#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    getline(cin >> ws, s);

    int count = 0;
    for (int i = 0; i < (int) s.length(); i++) {
        if (s[i] != ' ' && (i == 0 || s[i - 1] == ' ')) {
            count++;
        }
    }
    cout << count << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();

        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != ' ' && (i == 0 || s.charAt(i - 1) == ' ')) {
                count++;
            }
        }
        System.out.println(count);
    }
}
